package com.roebolet.vendor.engine

import com.roebolet.vendor.data.api.BetGrid
import com.roebolet.vendor.data.api.OpenDrawItem
import java.math.BigDecimal
import java.math.RoundingMode

/**
 * Modes de calcul de mise pour les combinaisons générées
 */
enum class BetCalculationMode {
    UNIT_BET,             // Mode 1 : Montant fixe par combinaison
    DISTRIBUTED_BUDGET,   // Mode 2 : Budget total réparti sans perte
    SOURCE_BASED          // Mode 3 : Calculé à partir des mises des numéros sources
}

/**
 * Règles pour le calcul de la mise basée sur les sources (Mode 3)
 */
enum class SourceBetRule {
    MINIMUM,    // Prend la plus petite mise des sources
    AVERAGE,    // Moyenne arrondie des mises des sources
    BASE_FIRST  // Prend la mise du premier numéro source
}

/**
 * Types de jeux gérés par le moteur
 */
enum class EngineGameType(val apiCode: String, val displayName: String, val maxDigits: Int) {
    BORLETTE("BORLETTE", "Bòlet", 2),
    LOTO3("LOTO3", "Loto 3", 3),
    LOTO4("LOTO4", "Loto 4", 4),
    LOTO5("LOTO5", "Loto 5", 5),
    MARIAGE("MARIAGE", "Maryaj", 5)
}

/**
 * Représentation d'une combinaison générée ou saisie
 */
data class GeneratedCombination(
    val number: String,
    val gameType: EngineGameType,
    val sourceNumbers: List<String> = emptyList(),
    var betAmount: Double = 0.0,
    val option: String = "TOUT",
    val isAutoGenerated: Boolean = true,
    var isManuallyEdited: Boolean = false,
    val isGratis: Boolean = false
) {
    val displayKey: String
        get() = "${gameType.apiCode}_$number"
}

/**
 * Configuration globale du moteur de combinaisons
 */
data class EngineConfig(
    val defaultPrefixLoto3: String = "1",
    val defaultPrefixLoto5: String = "1",
    val mariageSeparator: String = "X",
    val minBetAmount: Double = 1.0,
    val maxBetAmount: Double = 5000.0,
    val sourceBetRule: SourceBetRule = SourceBetRule.MINIMUM
)

/**
 * Résultat du calcul des totaux financiers
 */
data class TicketTotalResult(
    val boletTotal: Double,
    val loto3Total: Double,
    val loto4Total: Double,
    val loto5Total: Double,
    val mariageTotal: Double,
    val unitTotal: Double,
    val drawCount: Int,
    val grandTotal: Double,
    val totalCombinationCount: Int
)

/**
 * Résultat de validation d'un ticket avant émission
 */
data class ValidationResult(
    val isValid: Boolean,
    val errors: List<String> = emptyList(),
    val warnings: List<String> = emptyList()
)

/**
 * MOTEUR CENTRAL INTELLIGENT DE GÉNÉRATION ET DE CALCUL DE MISES
 * Conçu selon les principes de Clean Architecture, 100% testable indépendamment de l'UI.
 */
object CombinationEngine {

    /**
     * Nettoyage et normalisation d'un numéro pour préserver les zéros initiaux
     */
    fun normalizeSourceNumber(raw: String): String {
        val trimmed = raw.trim()
        if (trimmed.isEmpty()) return ""
        // Si un seul chiffre, on préfixe par un 0 (ex: "2" -> "02")
        return if (trimmed.length == 1 && trimmed[0].isDigit()) "0$trimmed" else trimmed
    }

    /**
     * Extraction et déduplication des numéros sources valides de la Borlette
     */
    fun extractCleanSources(rawSources: List<String>): List<String> {
        return rawSources
            .map { normalizeSourceNumber(it) }
            .filter { it.isNotEmpty() && it.all { c -> c.isDigit() } && it.length <= 2 }
            .distinct()
    }

    /**
     * C. GÉNÉRATION LOTO 4 (Règle officielle confirmée)
     * Exemple : Sources ["02", "20", "22"]
     * Résultat : ["0222", "2202", "2022", "2220", "0220", "2002"]
     * Chaque combinaison est formée de deux numéros sources distincts et conserve l'ordre de concaténation.
     */
    fun generateLoto4(
        sources: List<String>,
        option: String = "TOUT"
    ): List<GeneratedCombination> {
        val clean = extractCleanSources(sources)
        if (clean.size < 2) return emptyList()

        val results = mutableListOf<GeneratedCombination>()
        val seenCombinations = mutableSetOf<String>()

        for (i in clean.indices) {
            for (j in clean.indices) {
                if (i != j) {
                    val numA = clean[i]
                    val numB = clean[j]
                    val comb = numA + numB

                    if (!seenCombinations.contains(comb)) {
                        seenCombinations.add(comb)
                        results.add(
                            GeneratedCombination(
                                number = comb,
                                gameType = EngineGameType.LOTO4,
                                sourceNumbers = listOf(numA, numB),
                                option = option,
                                isAutoGenerated = true
                            )
                        )
                    }
                }
            }
        }
        return results
    }

    /**
     * D. GÉNÉRATION MARIAGE (Règle officielle confirmée)
     * Exemple : Sources ["02", "20", "22"]
     * Résultat : ["02X20", "02X22", "20X22"]
     * Paires non ordonnées uniques, format A + separator + B
     */
    fun generateMariage(
        sources: List<String>,
        separator: String = "X",
        option: String = "TOUT"
    ): List<GeneratedCombination> {
        val clean = extractCleanSources(sources)
        if (clean.size < 2) return emptyList()

        val results = mutableListOf<GeneratedCombination>()
        val seenPairs = mutableSetOf<String>()

        for (i in 0 until clean.size) {
            for (j in (i + 1) until clean.size) {
                val numA = clean[i]
                val numB = clean[j]

                // Tri alphabétique interne pour garantir l'unicité de la paire non ordonnée
                val sortedPairKey = if (numA <= numB) "${numA}_$numB" else "${numB}_$numA"

                if (!seenPairs.contains(sortedPairKey)) {
                    seenPairs.add(sortedPairKey)
                    val formatted = "$numA$separator$numB"
                    results.add(
                        GeneratedCombination(
                            number = formatted,
                            gameType = EngineGameType.MARIAGE,
                            sourceNumbers = listOf(numA, numB),
                            option = option,
                            isAutoGenerated = true
                        )
                    )
                }
            }
        }
        return results
    }

    /**
     * GÉNÉRATION LOTO 3
     * Préfixe 1 chiffre ("chif devan") + numéro source 2 chiffres -> 3 chiffres
     */
    fun generateLoto3(
        sources: List<String>,
        prefixes: List<String> = listOf("1")
    ): List<GeneratedCombination> {
        val clean = extractCleanSources(sources)
        if (clean.isEmpty()) return emptyList()

        val cleanPrefixes = prefixes
            .map { it.trim() }
            .filter { it.isNotEmpty() && it.all { c -> c.isDigit() } }
            .ifEmpty { listOf("1") }

        val results = mutableListOf<GeneratedCombination>()
        val seen = mutableSetOf<String>()

        for (p in cleanPrefixes) {
            for (s in clean) {
                val comb = "$p$s"
                if (!seen.contains(comb)) {
                    seen.add(comb)
                    results.add(
                        GeneratedCombination(
                            number = comb,
                            gameType = EngineGameType.LOTO3,
                            sourceNumbers = listOf(s),
                            isAutoGenerated = true
                        )
                    )
                }
            }
        }
        return results
    }

    /**
     * GÉNÉRATION LOTO 5
     * Préfixe 1 chiffre + 4 chiffres d'une paire source -> 5 chiffres
     */
    fun generateLoto5(
        sources: List<String>,
        prefixes: List<String> = listOf("1")
    ): List<GeneratedCombination> {
        val loto4List = generateLoto4(sources)
        if (loto4List.isEmpty()) return emptyList()

        val cleanPrefixes = prefixes
            .map { it.trim() }
            .filter { it.isNotEmpty() && it.all { c -> c.isDigit() } }
            .ifEmpty { listOf("1") }

        val results = mutableListOf<GeneratedCombination>()
        val seen = mutableSetOf<String>()

        for (p in cleanPrefixes) {
            for (l4 in loto4List) {
                val comb = "$p${l4.number}"
                if (!seen.contains(comb)) {
                    seen.add(comb)
                    results.add(
                        GeneratedCombination(
                            number = comb,
                            gameType = EngineGameType.LOTO5,
                            sourceNumbers = l4.sourceNumbers,
                            isAutoGenerated = true
                        )
                    )
                }
            }
        }
        return results
    }

    /**
     * Génère l'ensemble des combinaisons pour les jeux cibles sélectionnés
     */
    fun generateAllFromBolet(
        sources: List<String>,
        targetGames: Set<EngineGameType> = setOf(EngineGameType.LOTO4, EngineGameType.MARIAGE),
        config: EngineConfig = EngineConfig()
    ): List<GeneratedCombination> {
        val results = mutableListOf<GeneratedCombination>()
        if (targetGames.contains(EngineGameType.LOTO4)) {
            results.addAll(generateLoto4(sources))
        }
        if (targetGames.contains(EngineGameType.MARIAGE)) {
            results.addAll(generateMariage(sources, separator = config.mariageSeparator))
        }
        if (targetGames.contains(EngineGameType.LOTO3)) {
            results.addAll(generateLoto3(sources, prefixes = listOf(config.defaultPrefixLoto3)))
        }
        if (targetGames.contains(EngineGameType.LOTO5)) {
            results.addAll(generateLoto5(sources, prefixes = listOf(config.defaultPrefixLoto5)))
        }
        return results
    }

    /**
     * E. CALCUL DES MISES SELON LES 3 MODES
     */
    fun calculateBetAmounts(
        combinations: List<GeneratedCombination>,
        mode: BetCalculationMode,
        budgetOrUnitAmount: Double,
        sourceBets: Map<String, Double> = emptyMap(),
        sourceRule: SourceBetRule = SourceBetRule.MINIMUM
    ): List<GeneratedCombination> {
        if (combinations.isEmpty()) return emptyList()

        return when (mode) {
            // Mode 1 : Montant fixe par combinaison
            BetCalculationMode.UNIT_BET -> {
                val unit = budgetOrUnitAmount.coerceAtLeast(0.0)
                combinations.map {
                    if (it.isManuallyEdited) it else it.copy(betAmount = unit)
                }
            }

            // Mode 2 : Budget total réparti sans perte de centime ni dépassement
            BetCalculationMode.DISTRIBUTED_BUDGET -> {
                val totalBudgetCents = BigDecimal.valueOf(budgetOrUnitAmount.coerceAtLeast(0.0))
                    .multiply(BigDecimal.valueOf(100))
                    .setScale(0, RoundingMode.HALF_UP)
                    .toLong()

                // Filtrer les combinaisons dont la mise n'a pas été figée manuellement
                val flexibleCombs = combinations.filter { !it.isManuallyEdited }
                val manuallyAssignedCents = combinations
                    .filter { it.isManuallyEdited }
                    .sumOf { (it.betAmount * 100).toLong() }

                val remainingBudgetCents = (totalBudgetCents - manuallyAssignedCents).coerceAtLeast(0)

                if (flexibleCombs.isEmpty()) {
                    return combinations
                }

                val count = flexibleCombs.size.toLong()
                val baseCentsPerComb = remainingBudgetCents / count
                val remainderCents = (remainingBudgetCents % count).toInt()

                var assignedIndex = 0
                combinations.map { comb ->
                    if (comb.isManuallyEdited) {
                        comb
                    } else {
                        // Les 'remainderCents' premières combinaisons reçoivent 1 centime de plus
                        val extraCent = if (assignedIndex < remainderCents) 1 else 0
                        assignedIndex++
                        val finalCents = baseCentsPerComb + extraCent
                        val finalAmount = BigDecimal.valueOf(finalCents)
                            .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP)
                            .toDouble()
                        comb.copy(betAmount = finalAmount)
                    }
                }
            }

            // Mode 3 : Mise calculée à partir des numéros sources
            BetCalculationMode.SOURCE_BASED -> {
                combinations.map { comb ->
                    if (comb.isManuallyEdited) {
                        comb
                    } else {
                        val bets = comb.sourceNumbers.map { sourceBets[it] ?: budgetOrUnitAmount }
                        val computed = if (bets.isEmpty()) {
                            budgetOrUnitAmount
                        } else {
                            when (sourceRule) {
                                SourceBetRule.MINIMUM -> bets.minOrNull() ?: budgetOrUnitAmount
                                SourceBetRule.AVERAGE -> {
                                    val avg = bets.sum() / bets.size
                                    BigDecimal.valueOf(avg).setScale(2, RoundingMode.HALF_UP).toDouble()
                                }
                                SourceBetRule.BASE_FIRST -> bets.firstOrNull() ?: budgetOrUnitAmount
                            }
                        }
                        comb.copy(betAmount = computed.coerceAtLeast(0.0))
                    }
                }
            }
        }
    }

    /**
     * H. CALCUL DU TOTAL DU TICKET AVEC PRÉCISION MONÉTAIRE
     */
    fun calculateTicketTotal(
        grids: List<BetGrid>,
        drawCount: Int = 1
    ): TicketTotalResult {
        var boletSum = BigDecimal.ZERO
        var loto3Sum = BigDecimal.ZERO
        var loto4Sum = BigDecimal.ZERO
        var loto5Sum = BigDecimal.ZERO
        var mariageSum = BigDecimal.ZERO

        var totalCount = 0

        for (grid in grids) {
            val amt = BigDecimal.valueOf(if (grid.isGratis == true) 0.0 else grid.betAmount)
            totalCount++

            when (grid.gameType?.uppercase() ?: "BORLETTE") {
                "BORLETTE", "BOLET" -> boletSum = boletSum.add(amt)
                "LOTO3" -> loto3Sum = loto3Sum.add(amt)
                "LOTO4" -> loto4Sum = loto4Sum.add(amt)
                "LOTO5" -> loto5Sum = loto5Sum.add(amt)
                "MARIAGE", "MARYAJ" -> mariageSum = mariageSum.add(amt)
                else -> boletSum = boletSum.add(amt)
            }
        }

        val unitTotal = boletSum.add(loto3Sum).add(loto4Sum).add(loto5Sum).add(mariageSum)
        val validDrawCount = drawCount.coerceAtLeast(1)
        val grandTotal = unitTotal.multiply(BigDecimal.valueOf(validDrawCount.toLong()))

        return TicketTotalResult(
            boletTotal = boletSum.setScale(2, RoundingMode.HALF_UP).toDouble(),
            loto3Total = loto3Sum.setScale(2, RoundingMode.HALF_UP).toDouble(),
            loto4Total = loto4Sum.setScale(2, RoundingMode.HALF_UP).toDouble(),
            loto5Total = loto5Sum.setScale(2, RoundingMode.HALF_UP).toDouble(),
            mariageTotal = mariageSum.setScale(2, RoundingMode.HALF_UP).toDouble(),
            unitTotal = unitTotal.setScale(2, RoundingMode.HALF_UP).toDouble(),
            drawCount = validDrawCount,
            grandTotal = grandTotal.setScale(2, RoundingMode.HALF_UP).toDouble(),
            totalCombinationCount = totalCount
        )
    }

    /**
     * I. VALIDATION DU TICKET AVANT CONFIRMATION
     */
    fun validateTicket(
        grids: List<BetGrid>,
        selectedDraws: List<OpenDrawItem>,
        minBetAmount: Double = 1.0,
        maxBetAmount: Double = 5000.0,
        maxTicketAmount: Double = 50000.0
    ): ValidationResult {
        val errors = mutableListOf<String>()
        val warnings = mutableListOf<String>()

        if (selectedDraws.isEmpty()) {
            errors.add("Ou dwe chwazi omwen yon tiraj pou valide fich la.")
        }

        if (grids.isEmpty()) {
            errors.add("Fich la vid. Saisie omwen yon nimewo anvan ou valide.")
        }

        // Vérification des tirages sélectionnés
        for (draw in selectedDraws) {
            if (draw.status != "OPEN") {
                errors.add("Tiraj ${draw.game.name} #${draw.drawNumber} pa ouvè pou lavant.")
            }
        }

        // Vérification des doublons stricts à l'intérieur du ticket
        val seenKeys = mutableSetOf<String>()
        for (grid in grids) {
            val numStr = grid.numbers.joinToString("-")
            val gType = grid.gameType ?: "BORLETTE"
            val key = "${gType}_$numStr"
            if (seenKeys.contains(key)) {
                warnings.add("Nimewo $numStr repete nan menm jwèt la ($gType).")
            } else {
                seenKeys.add(key)
            }

            // Vérification des montants
            if (grid.isGratis != true) {
                if (grid.betAmount < minBetAmount) {
                    errors.add("Miz minimòm lan se $minBetAmount G pou nimewo $numStr.")
                }
                if (grid.betAmount > maxBetAmount) {
                    errors.add("Miz maksimòm lan se $maxBetAmount G depase pou nimewo $numStr.")
                }
            }
        }

        val totals = calculateTicketTotal(grids, selectedDraws.size)
        if (totals.grandTotal > maxTicketAmount) {
            errors.add("Total fich la (${totals.grandTotal} G) depase plafon otorize a ($maxTicketAmount G).")
        }

        return ValidationResult(
            isValid = errors.isEmpty(),
            errors = errors,
            warnings = warnings
        )
    }

    /**
     * J. EXTRACTION DE TOUTES LES BOULES (2 CHIFFRES) JOUÉES DANS LE TICKET
     * Règle d'exclusion absolue : Borlette, Loto 3, Loto 4, Loto 5, Mariage
     */
    fun extractAllPlayedBalls(grids: List<BetGrid>): Set<String> {
        val balls = mutableSetOf<String>()
        for (grid in grids) {
            if (grid.isGratis == true) continue

            val rawNumbers = grid.numbers
            for (raw in rawNumbers) {
                val clean = raw.trim().filter { it.isDigit() }
                when (clean.length) {
                    1 -> balls.add("0$clean")
                    2 -> balls.add(clean)
                    3 -> {
                        // Loto 3 : les 2 derniers chiffres et les 2 premiers
                        balls.add(clean.takeLast(2))
                        balls.add(clean.take(2))
                    }
                    4 -> {
                        // Loto 4 : les deux paires de 2 chiffres
                        balls.add(clean.substring(0, 2))
                        balls.add(clean.substring(2, 4))
                    }
                    5 -> {
                        // Loto 5 : préfixe + deux paires
                        balls.add(clean.substring(1, 3))
                        balls.add(clean.substring(3, 5))
                    }
                }
            }
        }
        return balls
    }

    /**
     * K. GÉNÉRATION DES 5 MARIAGES GRATUITS (RÈGLE DES 10 BOULES DISTINCTES)
     * 1. Exactement 5 mariages gratuits par ticket.
     * 2. Sélection de 10 boules au total (00 à 99).
     * 3. Les 10 boules sont TOUTES distinctes entre elles (zéro doublon).
     * 4. Exclusion absolue : aucune des 10 boules ne peut figurer parmi les numéros joués par le client.
     * 5. Génération stable et déterministe (reproductible tant que les numéros joués ne changent pas).
     * 6. Montant 0 G (isGratis = true, option = "GRATIS").
     */
    fun generateFiveFreeMarriages(
        paidGrids: List<BetGrid>,
        preferredSeed: Long? = null
    ): List<BetGrid> {
        val excludedBalls = extractAllPlayedBalls(paidGrids)

        // Bassin de 100 boules (00 à 99) filtré par exclusion stricte
        val availablePool = (0..99)
            .map { String.format(java.util.Locale.US, "%02d", it) }
            .filter { !excludedBalls.contains(it) }
            .toMutableList()

        if (availablePool.size < 10) {
            return emptyList()
        }

        // Graine déterministe basée sur les numéros joués ordonnés
        val signature = paidGrids
            .filter { it.isGratis != true }
            .map { "${it.gameType}_${it.numbers.joinToString("-")}" }
            .sorted()
            .joinToString(";")

        val seed = preferredSeed ?: (signature.hashCode().toLong() and 0xFFFFFFFFL)
        val rng = java.util.Random(seed)

        // Tirer exactement 10 boules distinctes sans remise
        val selectedBalls = mutableListOf<String>()
        for (i in 0 until 10) {
            val idx = rng.nextInt(availablePool.size)
            selectedBalls.add(availablePool.removeAt(idx))
        }

        // Former les 5 mariages gratuits (paires de 2 boules ordonnées)
        val freeMarriages = mutableListOf<BetGrid>()
        for (i in 0 until 5) {
            val numA = selectedBalls[i * 2]
            val numB = selectedBalls[i * 2 + 1]
            val pair = if (numA <= numB) listOf(numA, numB) else listOf(numB, numA)

            freeMarriages.add(
                BetGrid(
                    numbers = pair,
                    betAmount = 0.0,
                    multiplier = 1,
                    option = "GRATIS",
                    gameType = "MARIAGE",
                    isGratis = true
                )
            )
        }

        return freeMarriages
    }
}
